CAT = '15 · Safety & Environmental'


def _model(pid, title):
    return Model(pid, title, CAT, META[pid])


def _psv(name, x, y, z, r=0.04, mat='paint_red'):
    """Spring-loaded safety valve (vertical inlet at z, side outlet towards +x): body, bonnet, cap, outlet flange."""
    return join(name, [cyl(name + 'b', r * 1.4, z, z + r * 2.6, mat, 24, center=(x, y, 0)), cyl(name + 'bn', r * 0.9, z + r * 2.6, z + r * 6.0, mat, 24, center=(x, y, 0)),
                       cyl(name + 'cp', r * 0.6, z + r * 6.0, z + r * 7.0, mat, 16, center=(x, y, 0)), cyl(name + 'o', r * 1.1, x, x + r * 2.6, mat, 24, axis='X', center=(0, y, z + r * 1.3)),
                       cyl(name + 'of', r * 1.9, x + r * 2.4, x + r * 2.6, mat, 24, axis='X', center=(0, y, z + r * 1.3))])


def _detector(name, x, y, z, mat='paint_yellow', facing=(0, -1, 0), L=0.08, r=0.03):
    d = Vector(facing).normalized()
    b = Vector((x, y, z))
    return join(name, [sweep_tube(name + 'b', [tuple(b), tuple(b + d * L)], r, mat, 16), sweep_tube(name + 'w', [tuple(b + d * L), tuple(b + d * (L + 0.008))], r * 0.8, 'glass', 16)])


# =============================================================== EQ-346 Emergency pressure relief system
def emergency_pressure_relief_system(out):
    m = _model('emergency_pressure_relief_system', 'Emergency Pressure Relief System — Twin PSVs on a Change-over Valve, Rupture Disc & Relief Header')
    R, Z0, L = 0.45, 0.8, 2.0
    zt = Z0 + L + R * 0.5
    P(m, 'protected_vessel', 'Protected Pressure Vessel', 'vessel', vessel('pv', R, L, 0.012, 'paint_grey', heads=('2:1', '2:1'), z0=Z0), explode=(0, 0.7, 0), ref='epr_vessel')
    P(m, 'vessel_supports', 'Skirt / Legs', 'structure', legs('lg', R, 0.0, Z0 + 0.05, n=4), explode=(0, 0, -0.3), ref='epr_vessel', section='keep')
    lq = liquid_v('lq', R - 0.012, Z0, Z0 + 1.1, mat='water')
    pl = P(m, 'contents', 'Process Liquid (fire case: boiling, vapour generation)', 'fluid', lq, explode=(0, -0.4, 0), ref='epr_vessel', section='keep')
    droplets(m, 'vapour', 'Vapour generated by external fire', -0.25, 0.25, Z0 + 1.1, Z0 + 1.9, n=8, mat='steam', y=0.15, r=0.02)
    cv = [cyl('cvs', 0.06, zt - 0.01, zt + 0.25, 'steel', 24), box('cvb', (0.5, 0.18, 0.16), (0, 0, zt + 0.33), 'cast_iron'), cyl('cvh', 0.04, zt + 0.41, zt + 0.5, 'steel', 16), cyl('cvw', 0.09, zt + 0.5, zt + 0.52, 'paint_yellow', 24, r_in=0.075)]
    P(m, 'changeover_valve', 'Three-Way Change-over Valve (one PSV in service, one isolated for testing — never both closed)', 'valves', cv, explode=(0, 0, 0.4), ref='epr_changeover', section='keep')
    ps = []
    for k, x in enumerate((-0.18, 0.18)):
        ps.append(_psv(f'psv{k}', x, 0, zt + 0.41, r=0.045))
    P(m, 'safety_valves', 'Twin Spring-Loaded Safety Valves (PSV-A in service, PSV-B spare)', 'relief', ps, explode=(0, -0.3, 0.4), ref='epr_psv', section='keep')
    sp = P(m, 'psv_disc_spring', 'PSV-A Disc & Spring (lifts at set pressure, reseats at blowdown)', 'relief', [cyl('dsk', 0.05, zt + 0.52, zt + 0.535, 'chrome', 24, center=(-0.18, 0, 0)), spring('spr', (-0.18, 0, 0), 0.03, zt + 0.55, zt + 0.66, 0.006, turns=5, mat='steel')],
           explode=(0, -0.5, 0.5), ref='epr_psv', section='keep')
    keys_loop(m, sp, lambda t: (0, 0, 0.018 * smooth_pulse(t, 0.15, 0.4, 0.15)))
    rd = [None, join('rdn', [nozzle('rdz', (0.0, R, Z0 + 1.6), (0, 1, 0), 0.05, 0.25), cyl('rdd', 0.08, R + 0.25, R + 0.28, 'paint_red', 24, axis='Y', center=(0, 0, Z0 + 1.6))]),
          hollow_pipe('rdp', [(0.0, R + 0.28, Z0 + 1.6), (0.0, R + 0.5, Z0 + 1.6), (0.0, R + 0.5, zt + 1.0)], 0.05, 'steel', 16, bend=0.08)]
    P(m, 'rupture_disc', 'Rupture Disc on a Separate Nozzle (fast, full-bore relief for rapid events)', 'relief', rd[1:], explode=(0, 0.4, 0), ref='epr_disc', section='keep')
    hd = [hollow_pipe('ta', [(-0.063, 0, zt + 0.47), (0.0, 0, zt + 0.47), (0.0, 0, zt + 1.0), (2.6, 0, zt + 0.85)], 0.06, 'steel', 16, bend=0.1), hollow_pipe('tb', [(0.297, 0, zt + 0.47), (0.4, 0, zt + 0.47), (0.4, 0, zt + 0.97)], 0.05, 'steel', 16, bend=0.06)]
    hd += [hollow_pipe('hdr', [(0.0, R + 0.5, zt + 1.0), (0.0, 0.0, zt + 1.0)], 0.06, 'steel', 16), cyl('hdrs', 0.03, 0.0, zt + 0.95, 'paint_grey', 8, center=(2.4, 0, 0))]
    P(m, 'relief_header', 'Relief Header (self-draining, sloped to the flare knock-out drum)', 'piping', hd, explode=(0.4, 0, 0.4), ref='epr_header', section='keep')
    m.flow('relief', [(-0.18, 0, zt), (-0.18, 0, zt + 0.47), (0.0, 0, zt + 0.47), (0.0, 0, zt + 1.0), (2.7, 0, zt + 0.84)], 'steam', 0.02, 0.3)
    _ov(m, 'pressure', [cyl('pz', R + 0.05, Z0, Z0 + L, 'pressure_9', 64, r_in=R + 0.03), cyl('ph', 0.075, 0.0, 2.6, 'pressure_3', 24, axis='X', center=(0, 0, zt + 0.92), r_in=0.065)],
        'Relieve before the vessel is overstressed', 'Every pressure vessel needs relief for its credible overpressure scenarios (blocked outlet, fire, control-valve failure, runaway reaction). A PSV is set at or below '
        'the MAWP and sized for the worst relieving rate; allowable accumulation is typically 10 % (single valve), 16 % (multiple) or 21 % (fire case) above MAWP (ASME VIII / API 520 — verify edition). '
        'Inlet pressure loss should stay below ≈ 3 % of set pressure to avoid chatter. The change-over valve allows testing a spare without losing protection.')
    return m.export(out)


# =============================================================== EQ-347 Blowdown tank (boiler)
def blowdown_tank(out):
    m = _model('blowdown_tank', 'Boiler Blowdown Tank (Atmospheric Flash Tank with Vent, Quench & Drain)')
    R, Z0, L = 0.4, 0.6, 1.4
    zt = Z0 + L + R * 0.5
    P(m, 'tank', 'Blowdown Tank (vertical, wear plate at the tangential inlet)', 'vessel', [vessel('bt', R, L, 0.01, 'paint_grey', heads=('2:1', '2:1'), z0=Z0), legs('lg', R, 0.0, Z0 + 0.05, n=4)], explode=(0, 0.6, 0), ref='bdt_tank')
    wp = lathe('wp', [(R - 0.03, Z0 + 0.9), (R - 0.012, Z0 + 0.9), (R - 0.012, Z0 + 1.3), (R - 0.03, Z0 + 1.3)], 'steel_dark', 48, a0=-0.5, a1=1.2, cap_mat='steel_dark')
    P(m, 'wear_plate', 'Wear Plate (takes the erosive tangential jet)', 'internals', wp, explode=(0, -0.3, 0.2), ref='bdt_tank', section='keep')
    lq = liquid_v('lq', R - 0.01, Z0, Z0 + 0.55, mat='water')
    pl = P(m, 'water', 'Retained Water (water seal at the outlet)', 'fluid', lq, explode=(0, -0.4, 0), ref='bdt_tank', section='keep')
    animate_level(m, pl, Z0 + 0.4, 0.08, lambda t: smooth_pulse(t, 0.1, 0.3, 0.3))
    pp = [hollow_pipe('in', [(-1.4, 0.3, Z0 + 1.1), (-0.6, 0.3, Z0 + 1.1), (-0.3, 0.3, Z0 + 1.1)], 0.04, 'steel', 16), _valve('qv', (-1.0, 0.3, Z0 + 1.1), 'X', 0.04, 'cast_iron'),
          hollow_pipe('vt', [(0, 0, zt - 0.01), (0, 0, zt + 1.2)], 0.12, 'steel', 32), lathe('vh', [(0.0, zt + 1.2), (0.2, zt + 1.2), (0.2, zt + 1.25), (0.0, zt + 1.3)], 'steel', 24),
          hollow_pipe('dr', [(0, 0, Z0 - R * 0.5), (0, 0, 0.25), (0.9, 0, 0.25), (0.9, 0, Z0 + 0.5), (1.3, 0, Z0 + 0.5)], 0.05, 'steel', 16, bend=0.06),
          hollow_pipe('qw', [(1.4, 0.3, Z0 + 0.3), (0.6, 0.3, Z0 + 0.3), (0.6, 0.3, 0.3), (0.3, 0.1, 0.3)], 0.02, 'paint_blue', 8, bend=0.04), box('tcv', (0.08, 0.08, 0.1), (1.0, 0.3, Z0 + 0.3), 'brass'),
          box('ts', (0.04, 0.04, 0.06), (1.1, 0, Z0 + 0.5), 'paint_blue_dark'), pressure_gauge('pg', (0.3, -R, Z0 + 1.6), r=0.04, facing=(0, -1, 0))]
    P(m, 'piping', 'Tangential Blowdown Inlet, Atmospheric Vent with Separator Head, Siphon-Loop Drain, Cooling-Water Quench (temp-controlled)', 'piping', pp, explode=(0, 0, 0.4), ref='bdt_piping', section='keep')
    droplets(m, 'flash', 'Flash steam rising to the vent', -0.1, 0.1, Z0 + 1.0, zt + 1.2, n=8, mat='steam', y=0.05, r=0.025)
    add_tracers(m, 'swirl', 'Blowdown swirling around the shell', [(-0.3, 0.3, Z0 + 1.1)] + [(0.33 * math.cos(a), 0.33 * math.sin(a), Z0 + 1.1 - 0.2 * k / 16) for k, a in enumerate([math.pi / 2 + TAU * j / 16 for j in range(17)])], n=6, radius=0.02, mat='water')
    m.flow('blowdown_in', [(-1.5, 0.3, Z0 + 1.1), (-0.3, 0.3, Z0 + 1.1)], 'water', 0.02, 0.3)
    m.flow('vent', [(0, 0, zt), (0, 0, zt + 1.4)], 'steam', 0.03, 0.3)
    m.flow('drain', [(0, 0, Z0 - 0.2), (0, 0, 0.25), (0.9, 0, 0.25), (0.9, 0, Z0 + 0.5), (1.4, 0, Z0 + 0.5)], 'water', 0.015, 0.2)
    _ov(m, 'temperature', [cyl('t0', R + 0.05, Z0 + 0.9, Z0 + L, 'pressure_8', 48, r_in=R + 0.03), cyl('t1', R + 0.05, Z0, Z0 + 0.55, 'pressure_5', 48, r_in=R + 0.03), cyl('t2', 0.08, 0.6, 1.3, 'pressure_2', 24, axis='X', center=(0, 0, Z0 + 0.5), r_in=0.06)],
        'Flash it, vent it, cool it', 'Boiler blowdown leaves at boiler pressure and saturation temperature. Entering the vented tank tangentially, part of it flashes to steam (released through the vent) and the rest '
        'drops to ≈ 100 °C. Cooling water is added so the drain to the sewer stays below the permitted temperature (often ≤ ≈ 40–60 °C, local rules). The tank must never be pressurised: the vent is sized for '
        'the flash flow and must not be valved.')
    return m.export(out)


# =============================================================== EQ-348 Closed drain system
def closed_drain_system(out):
    m = _model('closed_drain_system', 'Closed Drain System — Equipment Drain Header, Underground Closed Drain Drum, Pump-Out Pump & Vent to Flare')
    pit = csg('pit', [box('pto', (3.2, 1.6, 1.6), (0.6, 0, -0.8), 'cast_iron')], [box('pti', (3.0, 1.4, 1.6), (0.6, 0, -0.7), 'cast_iron')], 'cast_iron')
    P(m, 'drum_pit', 'Concrete Pit (drum below grade so drains flow by gravity)', 'civil', pit, explode=(0, 0.6, -0.3), ref='cd_pit')
    gr = csg('grd', [box('gro', (5.4, 3.2, 0.06), (0.2, 0, -0.03), 'cast_iron')], [box('grh', (3.0, 1.4, 0.2), (0.6, 0, -0.03), 'cast_iron')], 'cast_iron')
    P(m, 'grade', 'Grade Slab (pit opening covered by removable gratings)', 'civil', [gr] + [box(f'gg{k}', (0.03, 1.4, 0.03), (-0.85 + 0.1 * k, 0, -0.015), 'steel_dark') for k in range(8)], explode=(0, 0, 0.3), ref='cd_pit', section='keep')
    R, CZ = 0.45, -0.9
    P(m, 'drain_drum', 'Closed Drain Drum (horizontal, on saddles)', 'vessel', [vessel('dd', R, 2.2, 0.01, 'paint_grey', axis='X', center=(0, 0, CZ), heads=('2:1', '2:1'), z0=-0.5), saddles('sd', (-0.1, 1.3), R, CZ, foot_z=-1.5)],
      explode=(0, 0.6, 0), ref='cd_drum')
    lq = liquid('lq', R - 0.01, -0.5, CZ - 0.05, mat='liquor', axis='X', center=(0, 0, 0), L=2.2, zt=CZ)
    pl = P(m, 'drained_liquid', 'Drained Hydrocarbon / Water', 'fluid', lq, explode=(0, -0.5, 0), ref='cd_drum', section='keep')
    animate_level(m, pl, CZ - 0.2, 0.25, lambda t: (t / 0.75) if t < 0.75 else (1 - (t - 0.75) / 0.25))
    eq = [vessel('e1', 0.3, 1.0, 0.008, 'paint_blue', heads=('2:1', '2:1'), z0=0.6, center=(-1.8, 0.4, 0)), legs('el1', 0.3, 0.0, 0.65, n=3, cx=-1.8, cy=0.4),
          cyl('e2', 0.25, -1.2, -0.5, 'paint_green', 32, axis='X', center=(0, 0.6, 0.6)), box('e2s', (0.1, 0.4, 0.35), (-0.85, 0.6, 0.18), 'paint_grey')]
    P(m, 'process_equipment', 'Process Equipment being Drained (vessel & exchanger)', 'equipment', eq, explode=(-0.3, 0.3, 0), ref='cd_equipment', section='keep')
    hdr = [hollow_pipe('d1', [(-1.8, 0.4, 0.45), (-1.8, 0.4, 0.2), (-1.8, 0.0, 0.1)], 0.03, 'steel', 12, bend=0.04), hollow_pipe('d2', [(-0.85, 0.6, 0.35), (-0.85, 0.6, 0.2), (-0.85, 0.0, 0.1)], 0.03, 'steel', 12, bend=0.04),
           hollow_pipe('hd', [(-1.9, 0.0, 0.12), (-0.5, 0.0, 0.05), (0.0, 0.0, -0.2), (0.0, 0.0, CZ + R - 0.01)], 0.05, 'steel', 16, bend=0.08), _valve('dv1', (-1.8, 0.4, 0.3), 'Z', 0.03, 'cast_iron'), _valve('dv2', (-0.85, 0.6, 0.27), 'Z', 0.03, 'cast_iron')]
    P(m, 'drain_header', 'Closed Drain Header (sloped, double block valves at each drain point)', 'piping', hdr, explode=(-0.2, 0, 0.3), ref='cd_header', section='keep')
    vt = [hollow_pipe('vt', [(0.8, 0.0, CZ + R - 0.01), (0.8, 0.0, 0.8), (2.4, 0.0, 0.8)], 0.05, 'steel', 16, bend=0.08), box('ftg', (0.15, 0.04, 0.15), (2.2, -0.05, 0.8), 'paint_yellow')]
    P(m, 'vent_to_flare', 'Vent to Flare Header (drum stays closed to atmosphere)', 'piping', vt, explode=(0.3, 0, 0.3), ref='cd_vent', section='keep')
    pu = [cyl('pc', 0.12, 0.25, 0.45, 'paint_blue', 32, center=(1.4, 0, 0)), cyl('pm', 0.1, 0.45, 0.85, 'paint_motor', 32, center=(1.4, 0, 0)), cyl('pcl', 0.06, CZ - R + 0.05, 0.25, 'steel', 24, center=(1.4, 0, 0)),
          hollow_pipe('pd', [(1.52, 0, 0.35), (1.9, 0, 0.35), (1.9, 0, 0.6), (2.4, 0, 0.6)], 0.035, 'steel', 12, bend=0.05), nozzle('dn', (1.4, 0, CZ + R), (0, 0, 1), 0.07, 0.01)]
    P(m, 'pump_out_pump', 'Vertical Pump-Out Pump (column into the drum; returns liquid to slop / process)', 'pumps', pu, explode=(0.3, -0.3, 0.3), ref='cd_pump', section='keep')
    ins = [box('lt', (0.06, 0.06, 0.15), (-0.3, -0.15, 0.32), 'paint_blue_dark'), cyl('lts', 0.02, CZ + 0.2, 0.25, 'steel', 8, center=(-0.3, -0.15, 0)),
           cyl('htc', 0.02, -0.4, 0.8, 'hot_glow', 8, axis='X', center=(0, 0.15, CZ - 0.3))]
    P(m, 'instruments', 'Level Transmitter (auto start/stop, high alarm) & Heating Coil (winter / viscous drains)', 'controls', ins, explode=(0, -0.3, 0.3), ref='cd_instr', section='keep')
    m.flow('drains', [(-1.8, 0.4, 0.45), (-1.8, 0.0, 0.1), (-0.5, 0.0, 0.05), (0.0, 0.0, -0.2), (0.0, 0.05, CZ)], 'flow_suction', 0.02, 0.3)
    m.flow('vapour', [(0.8, 0.0, CZ + R), (0.8, 0.0, 0.8), (2.5, 0.0, 0.8)], 'steam', 0.02, 0.3)
    m.flow('pump_out', [(1.4, 0.05, CZ - 0.3), (1.4, 0, 0.35), (1.9, 0, 0.35), (1.9, 0, 0.6), (2.5, 0, 0.6)], 'flow_discharge', 0.015, 0.3)
    _ov(m, 'pressure', [cyl('pz', R + 0.05, -0.5, 1.7, 'pressure_3', 48, axis='X', center=(0, 0, CZ), r_in=R + 0.03)], 'Hydrocarbons never see the atmosphere', 'A closed drain system collects pressurised '
        'or hazardous liquids drained from equipment (maintenance, start-up, level controller drains) in a closed drum that is vented to the flare, so vapours are not released to air and oxygen cannot get '
        'in. The drum sits low so drains flow by gravity; the header has no pockets. Closed and open drain systems must never be interconnected (vapour/fire spread).')
    return m.export(out)


# =============================================================== EQ-349 Open drain system
def open_drain_system(out):
    m = _model('open_drain_system', 'Open Drain System — Drain Hubs, Sealed Drain Boxes, Trench & Oily-Water Sump with Skimmer & Pump')
    sl = csg('sl', [box('slo', (4.0, 2.4, 0.15), (0, 0, -0.075), 'cast_iron')], [box('tr', (3.0, 0.3, 0.3), (0.2, -0.4, -0.05), 'cast_iron'), box('sp', (0.9, 0.9, 1.2), (1.9, -0.4, -0.5), 'cast_iron')], 'cast_iron')
    P(m, 'paved_area', 'Paved, Sloped & Curbed Process Area', 'civil', [sl] + [box(f'cb{k}', (4.0 if k < 2 else 0.12, 0.12 if k < 2 else 2.4, 0.15), ((0, 0, -1.94, 1.94)[k], (-1.14, 1.14, 0, 0)[k], 0.075), 'cast_iron') for k in range(4)],
      explode=(0, 0.4, -0.3), ref='od_area')
    tr = csg('trg', [box('tro', (3.2, 0.5, 0.45), (0.2, -0.4, -0.15), 'cast_iron')], [box('tri', (3.0, 0.3, 0.45), (0.2, -0.4, -0.05), 'cast_iron')], 'cast_iron')
    gr = [box(f'g{k}', (0.02, 0.32, 0.03), (-1.2 + 0.1 * k, -0.4, -0.015), 'steel_dark') for k in range(29)]
    P(m, 'trench_grating', 'Drain Trench with Grating (collects spills and rainwater)', 'drain', [tr] + gr, explode=(0, -0.4, -0.2), ref='od_trench', section='keep')
    ts = [(-1.2, 0.6), (0.0, 0.6)]
    hb = []
    for k, (x, y) in enumerate(ts):
        hb += [cyl(f'fn{k}', 0.12, 0.0, 0.12, 'cast_iron', 24, center=(x, y, 0), r_in=0.1), cyl(f'fp{k}', 0.05, -0.6, 0.0, 'cast_iron', 16, center=(x, y, 0), r_in=0.04),
               sweep_tube(f'ptrap{k}', [(x, y, -0.6), (x, y, -0.75), (x, y - 0.25, -0.75), (x, y - 0.25, -0.45), (x, y - 0.6, -0.45), (x, y - 0.9, -0.3)], 0.045, 'cast_iron', 12)]
    P(m, 'drain_hubs_seals', 'Drain Hubs / Funnels under Equipment with Water-Seal (P-trap) Lines to the Trench', 'drain', hb, explode=(0, 0.3, 0.3), ref='od_hubs', section='keep')
    eq = [box('p0', (0.6, 0.3, 0.3), (-1.2, 0.6, 0.35), 'paint_blue'), box('p1', (0.6, 0.3, 0.3), (0.0, 0.6, 0.35), 'paint_blue'), box('pb0', (0.7, 0.4, 0.05), (-1.2, 0.6, 0.18), 'paint_grey'), box('pb1', (0.7, 0.4, 0.05), (0.0, 0.6, 0.18), 'paint_grey')]
    P(m, 'equipment', 'Pumps with Drip Pans (spills / leaks)', 'equipment', eq, explode=(0, 0.3, 0), ref='od_hubs', section='keep')
    sm = csg('sm', [box('smo', (1.0, 1.0, 1.25), (1.9, -0.4, -0.525), 'cast_iron')], [box('smi', (0.84, 0.84, 1.25), (1.9, -0.4, -0.45), 'cast_iron')], 'cast_iron')
    P(m, 'sump', 'Oily-Water Sump (gas-sealed inlet, sloped floor)', 'sump', [sm, box('wir', (0.02, 0.84, 0.6), (1.75, -0.4, -0.55), 'steel')], explode=(0.4, 0, -0.3), ref='od_sump')
    w = [box('sw', (0.83, 0.42, 0.8), (1.9, -0.19, -0.66), 'water')]
    pw = P(m, 'sump_water', 'Collected Water with Floating Oil Layer', 'fluid', w + [box('so', (0.83, 0.42, 0.04), (1.9, -0.19, -0.24), 'hydraulic_oil')], explode=(0.4, -0.3, 0), ref='od_sump', section='keep')
    animate_level(m, pw, -0.5, 0.15, lambda t: 0.5 - 0.5 * math.cos(TAU * t))
    sk = [cyl('skd', 0.12, -0.28, -0.2, 'paint_orange', 24, center=(2.05, -0.2, 0)), hollow_pipe('skh', [(2.05, -0.2, -0.2), (2.05, -0.2, 0.3), (2.5, -0.2, 0.3)], 0.02, 'rubber', 8, bend=0.03)]
    P(m, 'oil_skimmer', 'Floating Oil Skimmer → Slop Oil', 'separation', sk, explode=(0.3, 0, 0.3), ref='od_skimmer', section='keep')
    pu = [cyl('pmc', 0.1, -0.95, -0.7, 'paint_blue', 24, center=(1.85, -0.55, 0)), cyl('pmm', 0.08, -0.7, -0.4, 'paint_blue', 24, center=(1.85, -0.55, 0)),
          hollow_pipe('pmd', [(1.85, -0.45, -0.7), (1.85, -0.45, 0.3), (2.5, -0.45, 0.3)], 0.03, 'steel', 12, bend=0.04), cyl('fs', 0.005, -0.85, 0.0, 'rubber', 6, center=(1.65, -0.7, 0)), ball('fsb', 0.04, 'paint_orange', (1.65, -0.7, -0.55))]
    P(m, 'sump_pump', 'Submersible Sump Pump with Float Switch → Oily-Water Separator', 'pumps', pu, explode=(0.4, -0.3, 0.3), ref='od_pump', section='keep')
    for k, (x, y) in enumerate(ts):
        add_tracers(m, f'spill_{k + 1}', f'Spill from pump {k + 1} into the drain hub', [(x, y, 0.15), (x, y, -0.6), (x, y - 0.25, -0.75), (x, y - 0.25, -0.45), (x, y - 0.9, -0.3), (x + 0.4, -0.4, -0.25)], n=3, radius=0.018, mat='hydraulic_oil')
    m.flow('trench', [(-1.3, -0.4, -0.2), (1.3, -0.4, -0.25), (1.75, -0.4, -0.3)], 'water', 0.02, 0.3)
    m.flow('to_ows', [(1.85, -0.45, -0.7), (1.85, -0.45, 0.3), (2.6, -0.45, 0.3)], 'flow_discharge', 0.015, 0.3)
    _ov(m, 'pressure', [box('sz', (0.12, 0.2, 0.32), (-1.2, 0.35, -0.6), 'pressure_6'), box('sz2', (0.12, 0.2, 0.32), (0.0, 0.35, -0.6), 'pressure_6')], 'Water seals stop vapour and fire travelling',
        'Open drains take non-pressurised spills, leaks and rainwater from paved, curbed areas. Each drain hub connects through a liquid seal (P-trap or sealed catch basin) so flammable vapour and flame '
        'cannot travel through the drain network from one area to another; seals must be kept topped up. Oily water flows to a sump and on to an oil–water separator; the skimmer removes floating oil.')
    return m.export(out)


# =============================================================== EQ-350 Flare stack
def flare_stack(out):
    m = _model('flare_stack', 'Elevated Flare Stack — Water-Seal Drum, Riser, Molecular Seal, Steam-Assisted Tip & Pilots')
    H = 6.0
    sd = [vessel('sd', 0.45, 1.6, 0.01, 'paint_grey', axis='X', center=(0, 0, 0.6), heads=('2:1', '2:1'), z0=-1.8), saddles('sds', (-1.5, -0.5), 0.45, 0.6)]
    P(m, 'seal_drum', 'Liquid (Water) Seal Drum — prevents flashback and air ingress', 'vessel', sd, explode=(-0.4, 0.5, 0), ref='fl_seal')
    sw = liquid('sw', 0.44, -1.8, 0.5, mat='water', axis='X', center=(0, 0, 0), L=1.6, zt=0.6)
    P(m, 'seal_water', 'Seal Water', 'fluid', sw, explode=(-0.4, -0.3, 0), ref='fl_seal', section='keep')
    dp = hollow_pipe('dip', [(-3.2, 0, 1.2), (-1.4, 0, 1.2), (-1.4, 0, 0.4)], 0.12, 'steel', 24, bend=0.15)
    P(m, 'inlet_dip_leg', 'Flare Header Inlet & Dip Leg (gas bubbles through the water seal)', 'piping', dp, explode=(-0.4, 0, 0.3), ref='fl_seal', section='keep')
    rs = csg('rs', [cyl('rso', 0.18, 0.0, H, 'paint_grey', 48, center=(0.6, 0, 0)), cyl('rsb', 0.5, 0.0, 0.06, 'paint_grey', 48, center=(0.6, 0, 0))], [cyl('rsi', 0.17, 0.06, H + 0.1, 'paint_grey', 48, center=(0.6, 0, 0))], 'paint_grey')
    P(m, 'riser', 'Flare Riser / Stack (self-supported)', 'stack', [rs, hollow_pipe('x1', [(-0.25, 0, 1.05), (0.6, 0, 1.05)], 0.12, 'steel', 24)], explode=(0.4, 0.4, 0), ref='fl_riser')
    ms = [cyl('ms', 0.26, H - 1.0, H - 0.4, 'paint_grey', 48, center=(0.6, 0, 0), r_in=0.25), cyl('msc', 0.26, H - 0.4, H - 0.36, 'paint_grey', 48, center=(0.6, 0, 0))]
    P(m, 'molecular_seal', 'Molecular (Gas) Seal — reduces purge gas needed to keep air out', 'stack', ms, explode=(0.5, 0, 0.2), ref='fl_riser', section='keep')
    tp = [cyl('tp', 0.2, H, H + 0.5, 'stainless', 48, center=(0.6, 0, 0), r_in=0.18), _torus('sr', 0.25, 0.025, H + 0.45, 'steel', axis='Z', cy=0.6, cz=0.0)]
    tp += [rotate(cyl(f'sn{k}', 0.01, H + 0.45, H + 0.55, 'steel', 8, center=(0.85, 0, 0)), TAU * k / 12, 'Z', (0.6, 0, 0)) for k in range(12)]
    tp += [hollow_pipe('st', [(1.4, 0.2, 0.3), (1.4, 0.2, H + 0.45), (0.85, 0.0, H + 0.45)], 0.03, 'steel', 12, bend=0.08)]
    P(m, 'flare_tip', 'Flare Tip with Steam Ring & Injectors (smokeless burning)', 'tip', tp, explode=(0.5, 0, 0.6), ref='fl_tip', section='keep')
    pl = [rotate(join(f'pl{k}', [cyl(f'plp{k}', 0.015, 0.3, H + 0.55, 'steel', 8, center=(0.84, 0, 0)), box(f'plh{k}', (0.06, 0.06, 0.1), (0.84, 0, H + 0.6), 'paint_red')]), TAU * k / 3 + 0.4, 'Z', (0.6, 0, 0)) for k in range(3)]
    pl += [box('fpg', (0.5, 0.3, 0.8), (2.2, 0, 0.4), 'paint_grey'), hollow_pipe('ffg', [(2.2, 0, 0.8), (2.2, 0, 1.2), (1.0, 0, 1.2)], 0.015, 'steel', 8, bend=0.04)]
    P(m, 'pilots_ignition', 'Continuous Pilots, Flame-Front Generator / Ignition Panel & Pilot Gas', 'ignition', pl, explode=(0.5, 0.4, 0.2), ref='fl_pilots', section='keep')
    _flame(m, 'flare_flame', 'Flare Flame', (0.6, 0, H + 0.55), (0.25, 0, 1), 1.6, 0.3, 'fl_tip')
    for k in range(3):
        a = TAU * k / 3 + 0.4
        _flame(m, f'pilot_flame_{k + 1}', f'Pilot Flame {k + 1}', (0.6 + 0.24 * math.cos(a), 0.24 * math.sin(a), H + 0.65), (0, 0, 1), 0.18, 0.03, 'fl_pilots')
    droplets(m, 'bubbles', 'Relief gas bubbling through the water seal', -1.5, -1.3, 0.35, 0.95, n=6, mat='air', y=0.05, r=0.03)
    m.flow('flare_gas', [(-3.3, 0, 1.2), (-1.4, 0, 1.2), (-1.4, 0, 0.4), (-0.8, 0.05, 0.85), (-0.25, 0, 1.05), (0.6, 0, 1.05), (0.6, 0, H + 0.5)], 'flue_gas', 0.04, 0.6)
    m.flow('steam', [(1.4, 0.2, 0.3), (1.4, 0.2, H + 0.45), (0.85, 0.0, H + 0.45)], 'steam', 0.02, 0.4)
    _ov(m, 'temperature', [cyl('rz', 1.6, 0.0, 0.03, 'pressure_8', 64, center=(0.6, 0, 0), r_in=1.2), cyl('rz2', 3.0, 0.0, 0.03, 'pressure_4', 64, center=(0.6, 0, 0), r_in=1.6)], 'Radiation sets the stack height',
        'A flare safely burns gas released by relief valves and blowdown. Its height and location are set so thermal radiation at grade stays within limits (e.g. ≈ 1.58 kW/m² for continuous exposure of '
        'personnel, higher for short emergency exposure — API 521, verify edition). Steam (or air) injected at the tip mixes air into the flame for smokeless burning; continuous pilots guarantee ignition; '
        'the water seal and purge gas with a molecular seal stop air entering and flashback.')
    return m.export(out)


# =============================================================== EQ-351 Flare knockout drum
def flare_knockout_drum(out):
    m = _model('flare_knockout_drum', 'Flare Knockout Drum (Horizontal, Split Entry) with Pump-Out Pumps & Heating Coil')
    R, CZ, X0, L = 0.75, 1.0, -2.0, 4.0
    P(m, 'drum', 'Flare KO Drum (sized so liquid droplets ≥ ≈ 300–600 µm drop out)', 'vessel', [vessel('kd', R, L, 0.012, 'paint_grey', axis='X', center=(0, 0, CZ), heads=('2:1', '2:1'), z0=X0), saddles('ks', (-1.3, 1.3), R, CZ)],
      explode=(0, 0.8, 0), ref='fko_drum')
    lq = liquid('kl', R - 0.012, X0, CZ - 0.35, mat='liquor', axis='X', center=(0, 0, 0), L=L, zt=CZ)
    pl = P(m, 'liquid', 'Collected Hydrocarbon Liquid & Water', 'fluid', lq, explode=(0, -0.5, 0), ref='fko_drum', section='keep')
    animate_level(m, pl, CZ - 0.5, 0.15, lambda t: (t / 0.7) if t < 0.7 else (1 - (t - 0.7) / 0.3))
    nz = [hollow_pipe('i1', [(-1.6, -0.55, CZ + 1.4), (-1.6, -0.55, CZ + 1.1), (-1.6, 0, CZ + 1.1), (-1.6, 0, CZ + R - 0.01)], 0.15, 'steel', 32, bend=0.15),
          hollow_pipe('i2', [(1.6, -0.55, CZ + 1.4), (1.6, -0.55, CZ + 1.1), (1.6, 0, CZ + 1.1), (1.6, 0, CZ + R - 0.01)], 0.15, 'steel', 32, bend=0.15),
          hollow_pipe('hdr', [(-1.6, -0.55, CZ + 1.4), (1.6, -0.55, CZ + 1.4)], 0.15, 'steel', 32), hollow_pipe('in', [(0, -1.6, CZ + 1.4), (0, -0.55, CZ + 1.4)], 0.18, 'steel', 32),
          hollow_pipe('out', [(0, 0, CZ + R - 0.01), (0, 0, CZ + 2.1), (2.6, 0, CZ + 2.1)], 0.18, 'steel', 32, bend=0.2)]
    P(m, 'nozzles_piping', 'Split-Entry Inlets (both ends) & Central Vapour Outlet to the Flare', 'piping', nz, explode=(0, 0, 0.6), ref='fko_piping', section='keep')
    hc = [sweep_tube('hc', [(-1.5, 0.3, CZ - 0.6), (1.5, 0.3, CZ - 0.6), (1.5, 0.15, CZ - 0.6), (-1.5, 0.15, CZ - 0.6)], 0.025, 'hot_glow', 8), hollow_pipe('hcs', [(-1.5, 0.3, CZ - 0.6), (-2.2, 0.3, CZ - 0.6)], 0.025, 'steel', 8)]
    P(m, 'heating_coil', 'Steam Heating Coil (prevents freezing / keeps heavy liquids fluid)', 'thermal', hc, explode=(0, -0.3, -0.3), ref='fko_coil', section='keep')
    for k, y in enumerate((-0.4, 0.4)):
        _pump(m, f'pump_out_{k + 1}', f'Pump-Out Pump {k + 1} (' + ('duty' if k == 0 else 'standby') + ', auto on level)', 2.6, y, 0.25, 'fko_pumps', explode=(0.3, -0.3 if k == 0 else 0.3, 0))
    pp = [hollow_pipe(f'ps{k}', [(1.0, 0, CZ - R + 0.01), (1.0, 0, 0.6), (2.6, y, 0.6), (2.6, y, 0.37)], 0.05, 'steel', 16, bend=0.06) for k, y in enumerate((-0.4, 0.4))]
    pp += [box('lt', (0.08, 0.08, 0.5), (-0.5, -R - 0.08, CZ - 0.2), 'paint_blue_dark'), hollow_pipe('lc1', [(-0.5, -R - 0.04, CZ + 0.05), (-0.5, -R + 0.01, CZ + 0.05)], 0.015, 'steel', 8),
           hollow_pipe('lc2', [(-0.5, -R - 0.04, CZ - 0.45), (-0.5, -R + 0.05, CZ - 0.45)], 0.015, 'steel', 8)]
    P(m, 'pump_lines_level', 'Pump Suction Lines & Level Transmitter / Gauge (high-high level alarm)', 'piping', pp, explode=(0.2, -0.3, 0), ref='fko_level', section='keep')
    particles_path(m, 'droplets', 'Liquid droplets falling out of the slow-moving gas', lambda i, s: (-1.6 + 1.4 * s if i % 2 == 0 else 1.6 - 1.4 * s, 0.1 + 0.2 * ((i * 0.37) % 1), CZ + 0.6 - 0.95 * s * (0.6 + 0.4 * ((i * 0.53) % 1))), 12, mat='liquor', r=0.025)
    m.flow('relief_gas', [(0, -1.7, CZ + 1.4), (0, -0.55, CZ + 1.4), (-1.6, -0.55, CZ + 1.4), (-1.6, 0, CZ + 1.1), (-1.6, 0.05, CZ + 0.4), (0, 0.05, CZ + 0.4), (0, 0, CZ + 2.1), (2.7, 0, CZ + 2.1)], 'flue_gas', 0.04, 0.6)
    m.flow('pump_out', [(1.0, 0.05, CZ - 0.6), (1.0, 0, 0.6), (2.6, -0.4, 0.6), (2.6, -0.4, 0.37)], 'flow_discharge', 0.02, 0.3)
    _ov(m, 'pressure', [cyl('vz', R + 0.05, X0, X0 + L, 'pressure_2', 48, axis='X', center=(0, 0, CZ), r_in=R + 0.03)], 'Slow the gas so liquid drops out', 'Relief streams often carry liquid; a burning '
        'liquid rain from the flare is dangerous. The KO drum is sized (API 521 method) so the vapour velocity is low enough for droplets of ≈ 300–600 µm to settle in the travel time between inlet and '
        'outlet, and with hold-up volume for the liquid from the largest relief case for ≈ 20–30 min. It operates near atmospheric pressure, so pressure drop is kept small; pump-out pumps empty it.')
    return m.export(out)


# =============================================================== EQ-352 Gas scrubbing system (packed absorber + caustic)
def gas_scrubbing_system(out):
    m = _model('gas_scrubbing_system', 'Gas Scrubbing System — Packed Caustic Absorber, Recirculation, pH-Controlled Dosing, ID Fan & Stack')
    R, Z0, H = 0.5, 0.8, 3.0
    tw = csg('tw', [cyl('two', R + 0.015, Z0, Z0 + H, 'polypropylene', 64)], [cyl('twi', R, Z0 - 0.1, Z0 + H - 0.03, 'polypropylene', 64)], 'polypropylene')
    sm = csg('sm', [cyl('smo', R + 0.015, 0.05, Z0, 'polypropylene', 64)], [cyl('smi', R, 0.08, Z0 + 0.1, 'polypropylene', 64)], 'polypropylene')
    P(m, 'absorber', 'Absorber Tower (FRP) with Integral Sump', 'vessel', [tw, sm, cyl('tc', R + 0.015, Z0 + H - 0.03, Z0 + H, 'polypropylene', 64)], explode=(0, 0.7, 0), ref='gs_tower')
    P(m, 'packing', 'Random Packing (gas–liquid contact area)', 'internals', half(packing('pk', R - 0.01, Z0 + 0.6, Z0 + 2.0), 'rubber'), explode=(0, -0.6, 0), ref='gs_packing', section='keep')
    ds = [cyl('dh', 0.03, -R + 0.05, R - 0.05, 'polypropylene', 12, axis='X', center=(0, 0, Z0 + 2.3))] + [cyl(f'dn{k}', 0.02, Z0 + 2.2, Z0 + 2.28, 'polypropylene', 8, center=(x, 0, 0)) for k, x in enumerate((-0.3, 0.0, 0.3))]
    ds += [half(mesh_pad('me', R - 0.01, Z0 + 2.55, Z0 + 2.7), 'steel')]
    P(m, 'distributor_demister', 'Liquid Distributor / Spray Header & Mist Eliminator', 'internals', ds, explode=(0, -0.5, 0.4), ref='gs_distributor', section='keep')
    sl = lathe('sl', [(0.0, 0.08), (R - 0.005, 0.08), (R - 0.005, Z0 - 0.15), (0.0, Z0 - 0.15)], 'water', 64, a0=0.0, a1=math.pi, cap_mat='water')
    P(m, 'scrubbing_liquor', 'Scrubbing Liquor (dilute caustic, pH ≈ 8–10)', 'fluid', sl, explode=(0, -0.4, -0.2), ref='gs_tower', section='keep')
    _pump(m, 'recirc_pump', 'Recirculation Pump', 1.1, 0.0, 0.3, 'gs_pump', explode=(0.3, -0.3, 0))
    pp = [hollow_pipe('su', [(R, 0, 0.3), (1.1, 0, 0.3)], 0.04, 'polypropylene', 12), hollow_pipe('re', [(1.1, 0.0, 0.42), (1.1, 0.0, Z0 + 2.3), (R - 0.05, 0.0, Z0 + 2.3)], 0.04, 'polypropylene', 12, bend=0.06),
          vessel('ct', 0.25, 0.7, 0.006, 'polypropylene', heads=('flat', '2:1'), z0=0.05, center=(-1.2, 0.6, 0)), box('mp', (0.18, 0.14, 0.14), (-0.75, 0.6, 0.2), 'paint_blue'),
          hollow_pipe('cl', [(-1.2, 0.6, 0.1), (-0.84, 0.6, 0.2), (-0.66, 0.6, 0.2), (-0.4, 0.3, 0.5), (-R + 0.05, 0.1, 0.5)], 0.012, 'polypropylene', 8, bend=0.03),
          box('ph', (0.08, 0.06, 0.12), (0.75, 0.1, 0.6), 'paint_blue_dark'), hollow_pipe('bd', [(0.8, 0.0, 0.3), (0.8, -0.5, 0.3), (1.4, -0.5, 0.3)], 0.025, 'polypropylene', 8, bend=0.03)]
    P(m, 'liquor_circuit', 'Recirculation Line, Caustic Day Tank & Metering Pump (pH control), Blowdown of Spent Liquor', 'piping', pp, explode=(0, 0.4, 0.2), ref='gs_dosing', section='keep')
    gi = [hollow_pipe('gi', [(-2.0, 0, Z0 + 0.3), (-R + 0.01, 0, Z0 + 0.3)], 0.15, 'polypropylene', 24), hollow_pipe('go', [(0, 0, Z0 + H), (0, 0, Z0 + H + 0.4), (0.9, 0, Z0 + H + 0.4), (0.9, 0, Z0 + H + 0.1)], 0.15, 'polypropylene', 24, bend=0.15)]
    fc = csg('fc', [cyl('fco', 0.3, -0.12, 0.12, 'paint_blue', 48, axis='Y', center=(1.25, 0, Z0 + H - 0.2))], [cyl('fci', 0.28, -0.1, 0.1, 'paint_blue', 48, axis='Y', center=(1.25, 0, Z0 + H - 0.2))], 'paint_blue')
    gi += [fc, hollow_pipe('sk', [(1.25, 0, Z0 + H + 0.1), (1.25, 0, Z0 + H + 2.0)], 0.15, 'polypropylene', 24), box('fsup', (0.6, 0.6, Z0 + H - 0.5), (1.25, 0, (Z0 + H - 0.5) / 2), 'paint_grey')]
    P(m, 'gas_path', 'Gas Inlet Duct, Outlet Duct, ID Fan & Discharge Stack', 'ducts', gi, explode=(0.3, 0, 0.4), ref='gs_fan', section='keep')
    _fan_rotor(m, 'fan_impeller', 'ID Fan Impeller', (1.25, 0, Z0 + H - 0.2), 'Y', 0.24, 'gs_fan', revs=5)
    droplets(m, 'liquor_rain', 'Liquor trickling down through the packing', -0.3, 0.3, Z0 + 2.2, Z0 + 0.4, n=10, mat='water', y=0.15, r=0.015)
    m.flow('gas', [(-2.1, 0, Z0 + 0.3), (0, 0.05, Z0 + 0.4), (0, 0.05, Z0 + H), (0.9, 0, Z0 + H + 0.4), (1.25, 0, Z0 + H), (1.25, 0, Z0 + H + 2.1)], 'flue_gas', 0.03, 0.5)
    m.flow('liquor', [(R, 0, 0.3), (1.1, 0, 0.3), (1.1, 0, Z0 + 2.3), (0, 0, Z0 + 2.3)], 'water', 0.02, 0.4)
    _bands_z(m, [(Z0 + 1.6, Z0 + 2.0, 2), (Z0 + 1.1, Z0 + 1.6, 5), (Z0 + 0.6, Z0 + 1.1, 8)], R, 'Pollutant falls as gas rises through the packing',
             'Acid gases (e.g. H₂S, HCl, SO₂, Cl₂) are absorbed into the liquor and neutralised by caustic (e.g. H₂S + 2 NaOH → Na₂S + 2 H₂O). Counter-current flow keeps the strongest liquor meeting the '
             'cleanest gas, so removal can exceed 99 %. Design uses liquid-to-gas ratio, packing height (NTU × HTU) and pH control; spent liquor is bled off and fresh caustic added.', kind='pressure')
    return m.export(out)


# =============================================================== EQ-353 Wet scrubber (venturi + cyclonic separator)
def wet_scrubber(out):
    m = _model('wet_scrubber', 'Wet Scrubber — Venturi Throat with Cyclonic Separator (Particulate & Mist Removal)')
    vz = 1.8
    vt = csg('vtc', [lathe('vto', [(0.0, 3.0), (0.34, 3.0), (0.14, 2.35), (0.14, 2.15), (0.32, 1.6), (0.0, 1.6)], 'stainless', 64, center=(-1.0, 0, 0))],
             [lathe('vti', [(0.0, 3.05), (0.32, 3.05), (0.12, 2.35), (0.12, 2.15), (0.3, 1.55), (0.0, 1.55)], 'stainless', 64, center=(-1.0, 0, 0))], 'stainless')
    P(m, 'venturi', 'Venturi: Converging Section, Throat (gas ≈ 40–120 m/s) & Diverging Diffuser', 'venturi', [vt, cyl('vin', 0.32, 3.0, 3.5, 'stainless', 64, center=(-1.0, 0, 0), r_in=0.3)], explode=(-0.4, 0.4, 0), ref='ws_venturi')
    sp = [_torus('sr', 0.16, 0.02, 2.45, 'steel', axis='Z', cy=-1.0, cz=0.0)] + [rotate(cyl(f'sn{k}', 0.008, 2.36, 2.45, 'steel', 8, center=(-0.86, 0, 0)), TAU * k / 8, 'Z', (-1.0, 0, 0)) for k in range(8)]
    sp += [hollow_pipe('sw', [(0.6, 0.0, 0.3), (0.6, 0.6, 0.3), (0.6, 0.6, 2.45), (-0.84, 0.0, 2.45)], 0.03, 'paint_blue', 12, bend=0.06)]
    P(m, 'liquid_injection', 'Scrubbing-Liquid Injection Ring at the Throat Inlet', 'piping', sp, explode=(-0.4, -0.3, 0.3), ref='ws_spray', section='keep')
    el = hollow_pipe('el', [(-1.0, 0, 1.6), (-1.0, 0, 1.25), (-0.55, 0, 1.25)], 0.3, 'stainless', 32, bend=0.25)
    sep = csg('sep', [cyl('so', 0.55, 0.6, 2.8, 'stainless', 64, center=(0.2, 0, 0)), lathe('scn', [(0.0, 0.25), (0.08, 0.25), (0.55, 0.6), (0.0, 0.6)], 'stainless', 64, center=(0.2, 0, 0))],
              [cyl('si', 0.53, 0.62, 2.78, 'stainless', 64, center=(0.2, 0, 0)), lathe('sci', [(0.0, 0.27), (0.06, 0.27), (0.53, 0.62), (0.0, 0.62)], 'stainless', 64, center=(0.2, 0, 0))], 'stainless')
    P(m, 'cyclonic_separator', 'Cyclonic Separator (tangential entry; droplets thrown to the wall)', 'vessel', [el, sep, cyl('sc', 0.555, 2.78, 2.82, 'stainless', 64, center=(0.2, 0, 0)), legs('sl', 0.55, 0.0, 1.2, n=4, cx=0.2)], explode=(0.4, 0.5, 0), ref='ws_separator')
    P(m, 'separator_outlet', 'Clean-Gas Outlet Pipe & Chevron Mist Eliminator', 'internals', [hollow_pipe('go', [(0.2, 0, 1.6), (0.2, 0, 3.4)], 0.2, 'stainless', 32), half(mesh_pad('cm', 0.52, 2.4, 2.55, center=(0.2, 0, 0)), 'steel')],
      explode=(0.4, -0.3, 0.4), ref='ws_separator', section='keep')
    sl = lathe('slq', [(0.0, 0.28), (0.07, 0.28), (0.4, 0.5), (0.0, 0.5)], 'sludge', 48, a0=0.0, a1=math.pi, center=(0.2, 0, 0), cap_mat='sludge')
    P(m, 'slurry', 'Collected Slurry', 'fluid', sl, explode=(0.4, -0.3, -0.2), ref='ws_separator', section='keep')
    _pump(m, 'recycle_pump', 'Recycle Pump (bleed of slurry to treatment)', 0.6, 0.0, 0.3, 'ws_pump', explode=(0.3, -0.3, 0))
    P(m, 'recycle_line', 'Separator Drain to Recycle Pump', 'piping', [hollow_pipe('rd', [(0.2, 0, 0.25), (0.2, 0, 0.12), (0.45, 0, 0.12), (0.6, 0, 0.18)], 0.04, 'stainless', 12, bend=0.04)], explode=(0.3, 0, -0.2), ref='ws_pump', section='keep')
    particles_path(m, 'dust', 'Dust particles captured by atomised droplets in the throat', lambda i, s: (-1.0 + 0.1 * math.sin(i * 2.1) * (1 - s), 0.05, 3.3 - 1.7 * s), 12, mat='powder', r=0.02)
    add_tracers(m, 'swirl', 'Droplets spun to the wall and drained', [(-0.55, 0.0, 1.25)] + [(0.2 + 0.45 * math.cos(a), 0.45 * math.sin(a), 1.3 - 0.6 * k / 16) for k, a in enumerate([math.pi + TAU * j / 16 for j in range(17)])], n=6, radius=0.03, mat='sludge')
    m.flow('gas', [(-1.0, 0, 3.6), (-1.0, 0, 1.4), (-0.6, 0, 1.25), (0.0, 0.3, 1.4), (0.2, 0.05, 2.0), (0.2, 0, 3.5)], 'flue_gas', 0.035, 0.5)
    m.flow('liquid', [(0.6, 0.6, 0.3), (0.6, 0.6, 2.45), (-0.84, 0.0, 2.45)], 'water', 0.02, 0.3)
    _ov(m, 'pressure', [cyl('pt', 0.18, 2.15, 2.35, 'pressure_1', 48, center=(-1.0, 0, 0), r_in=0.15), cyl('pi', 0.36, 2.9, 3.0, 'pressure_7', 48, center=(-1.0, 0, 0), r_in=0.34), cyl('pd', 0.36, 1.6, 1.7, 'pressure_5', 48, center=(-1.0, 0, 0), r_in=0.33)],
        'Energy in the throat buys efficiency', 'Gas accelerates to high velocity in the venturi throat and shatters the injected liquid into fine droplets; dust particles impact them because of the large '
        'relative velocity. Collection efficiency rises with throat pressure drop (often ≈ 25–100 mbar for fine particulate) — the fan power pays for it. The diffuser recovers part of the pressure, and the '
        'cyclonic separator then removes the dirty droplets. Wet scrubbers also cool and saturate the gas and can absorb soluble gases.')
    return m.export(out)


# =============================================================== EQ-354 Dry scrubber (dry sorbent injection + reactor)
def dry_scrubber(out):
    m = _model('dry_scrubber', 'Dry Scrubber — Dry Sorbent Injection (Hydrated Lime / Sodium Bicarbonate) with Reaction Chamber & Recirculation')
    zc = 0.5
    sl = [silo('ss', 0.5, 1.4, 3.2, 'paint_grey', cx=-2.4, cy=0.6), legs('sll', 0.5, 0.0, 1.45, n=4, cx=-2.4, cy=0.6), box('sv', (0.15, 0.15, 0.15), (-2.4, 0.6, 1.0), 'paint_grey')]
    P(m, 'sorbent_silo', 'Sorbent Silo with Bin Vent & Rotary Feeder', 'storage', sl, explode=(-0.4, 0.4, 0), ref='ds_silo')
    fd = [box('bl', (0.35, 0.3, 0.3), (-2.4, -0.3, 0.3), 'paint_blue'), hollow_pipe('cv', [(-2.4, 0.6, 0.92), (-2.4, 0.6, 0.6), (-2.4, 0.0, 0.6), (-2.4, -0.3, 0.45)], 0.04, 'steel', 12, bend=0.04),
          hollow_pipe('pl', [(-2.22, -0.3, 0.3), (-1.6, -0.3, 0.3), (-1.6, 0.0, 0.3), (-1.6, 0.0, zc + 0.6)], 0.04, 'steel', 12, bend=0.06)]
    P(m, 'feeder_conveying', 'Loss-in-Weight Feeder, Mill (option) & Pneumatic Conveying Blower to the Injection Lances', 'conveying', fd, explode=(-0.3, -0.3, 0), ref='ds_feed', section='keep')
    du = csg('du', [box('duo', (2.2, 0.6, 0.6), (-0.5, 0, zc + 0.6), 'paint_grey')], [box('dui', (2.3, 0.54, 0.54), (-0.5, 0, zc + 0.6), 'paint_grey')], 'paint_grey')
    P(m, 'flue_duct', 'Flue-Gas Duct (from boiler / kiln / incinerator)', 'ducts', du, explode=(0, 0.5, 0), ref='ds_duct')
    la = [rotate(cyl(f'ln{k}', 0.02, -0.3, 0.1, 'stainless', 8, axis='Y', center=(-1.6 + 0.0, 0, zc + 0.45 + 0.15 * k)), 0, 'Z') for k in range(3)]
    P(m, 'injection_lances', 'Injection Lances (spread sorbent across the duct)', 'piping', la, explode=(0, -0.3, 0.2), ref='ds_feed', section='keep')
    rc = csg('rc', [cyl('rco', 0.6, zc + 0.3, 4.0, 'paint_grey', 64, center=(1.2, 0, 0)), lathe('rcc', [(0.0, zc - 0.3), (0.15, zc - 0.3), (0.6, zc + 0.3), (0.0, zc + 0.3)], 'paint_grey', 64, center=(1.2, 0, 0))],
             [cyl('rci', 0.58, zc + 0.3, 4.1, 'paint_grey', 64, center=(1.2, 0, 0)), lathe('rcci', [(0.0, zc - 0.28), (0.13, zc - 0.28), (0.58, zc + 0.32), (0.0, zc + 0.32)], 'paint_grey', 64, center=(1.2, 0, 0)),
              box('rcin', (0.4, 0.54, 0.54), (0.6, 0, zc + 0.6), 'paint_grey')], 'paint_grey')
    P(m, 'reaction_chamber', 'Reaction Chamber / Up-flow Reactor (residence time ≈ 2–5 s)', 'reactor', [rc, legs('rcl', 0.6, 0.0, zc + 0.35, n=4, cx=1.2)], explode=(0.5, 0.5, 0), ref='ds_reactor')
    ot = [hollow_pipe('ot', [(1.2, 0, 4.0), (1.2, 0, 4.4), (2.6, 0, 4.4), (2.6, 0, 3.6)], 0.25, 'paint_grey', 24, bend=0.3), box('bf', (0.8, 0.8, 1.6), (2.6, 0, 2.8), 'paint_grey'),
          hollow_pipe('rec', [(2.6, 0.3, 2.0), (2.6, 0.3, 1.6), (1.2, 0.3, 1.0)], 0.06, 'steel', 12, bend=0.08)] + [box(f'bfl{k}', (0.08, 0.08, 2.0), (2.6 + sx * 0.36, sy * 0.36, 1.0), 'paint_grey') for k, (sx, sy) in enumerate(((-1, -1), (-1, 1), (1, -1), (1, 1)))]
    P(m, 'outlet_filter', 'Outlet to Fabric Filter (product + unreacted sorbent collected) & Solids Recirculation Line', 'ducts', ot, explode=(0.5, 0, 0.4), ref='ds_filter', section='keep')
    particles_path(m, 'sorbent', 'Sorbent particles reacting with acid gas as they rise', lambda i, s: (-1.6 + 2.8 * min(1.0, s * 2.0) if s < 0.5 else 1.2 + 0.4 * math.sin(i + s * 9) * 0.5, 0.1 + 0.15 * ((i * 0.37) % 1),
                                                                                                     zc + 0.6 if s < 0.5 else zc + 0.6 + 3.2 * (s - 0.5) * 2 * 0.95), 16, mat='powder', r=0.025)
    m.flow('flue_gas', [(-1.7, 0, zc + 0.6), (1.2, 0.05, zc + 0.6), (1.2, 0.05, 4.0), (1.2, 0, 4.4), (2.6, 0, 4.4), (2.6, 0, 3.6)], 'flue_gas', 0.04, 0.6)
    m.flow('sorbent', [(-2.22, -0.3, 0.3), (-1.6, -0.3, 0.3), (-1.6, 0.0, zc + 0.6)], 'sand', 0.02, 0.3)
    _bands_z(m, [(zc + 0.3, 1.6, 8), (1.6, 2.8, 5), (2.8, 4.0, 2)], 0.6, 'Acid gas falls as sorbent reacts', 'Fine dry sorbent injected into the hot flue gas reacts with acid gases: Ca(OH)₂ + SO₂ → CaSO₃ + H₂O, '
             'Ca(OH)₂ + 2 HCl → CaCl₂ + 2 H₂O (or sodium bicarbonate, which decomposes to very reactive Na₂CO₃ above ≈ 140 °C). Removal depends on temperature, residence time, mixing and the stoichiometric ratio '
             '(often 1.5–3); the fabric filter cake adds further contact. No liquid effluent — the product is a dry powder; recirculation improves sorbent use.', kind='pressure', cx=1.2)
    return m.export(out)


# =============================================================== EQ-355 Baghouse dust collector (pulse-jet)
def baghouse_dust_collector(out):
    m = _model('baghouse_dust_collector', 'Baghouse Dust Collector — Pulse-Jet Bags & Cages, Tubesheet, Blowpipes, Hopper & Rotary Valve')
    W, D, Zt = 1.6, 1.2, 3.0
    cs = csg('cs', [box('cso', (W, D, 2.2), (0, 0, 2.1), 'paint_grey'), lathe('hpo', [(0.0, 0.6), (0.18, 0.6), (W * 0.72, 1.0), (0.0, 1.0)], 'paint_grey', 4, a0=math.pi / 4, a1=math.pi / 4 + TAU)],
             [box('csi', (W - 0.04, D - 0.04, 2.3), (0, 0, 2.1), 'paint_grey'), lathe('hpi', [(0.0, 0.62), (0.16, 0.62), (W * 0.7, 1.02), (0.0, 1.02)], 'paint_grey', 4, a0=math.pi / 4, a1=math.pi / 4 + TAU),
              box('inl', (0.3, 0.5, 0.5), (-W / 2, 0, 1.4), 'paint_grey'), box('ol', (0.3, 0.5, 0.4), (W / 2, 0, 3.0), 'paint_grey')], 'paint_grey')
    P(m, 'casing_hopper', 'Casing (dirty-gas chamber), Pyramid Hopper & Clean-Air Plenum', 'casing', [cs, box('tsh', (W - 0.04, D - 0.04, 0.02), (0, 0, 2.75), 'steel'), box('roof', (W + 0.04, D + 0.04, 0.03), (0, 0, 3.215), 'paint_grey'),
                                                                                                    csg('idu', [box('ido', (0.7, 0.54, 0.54), (-W / 2 - 0.35, 0, 1.4), 'paint_grey')], [box('idi', (0.8, 0.5, 0.5), (-W / 2 - 0.35, 0, 1.4), 'paint_grey')], 'paint_grey'),
                                                                                                    csg('odu', [box('odo', (0.6, 0.54, 0.44), (W / 2 + 0.3, 0, 3.0), 'paint_grey')], [box('odi', (0.7, 0.5, 0.4), (W / 2 + 0.3, 0, 3.0), 'paint_grey')], 'paint_grey')] + [box(f'lg{k}', (0.1, 0.1, 1.0), (sx * (W / 2 - 0.05), sy * (D / 2 - 0.05), 0.5), 'paint_grey') for k, (sx, sy) in enumerate(((-1, -1), (-1, 1), (1, -1), (1, 1)))],
      explode=(0, 0.8, 0), ref='bh_casing')
    xs = [-0.55, -0.18, 0.18, 0.55]
    ys = [-0.35, 0.0, 0.35]
    bg = []
    for i, x in enumerate(xs):
        for j, y in enumerate(ys):
            bg += [cyl(f'cg{i}{j}', 0.068, 1.27, 2.75, 'steel', 8, center=(x, y, 0), r_in=0.066), cyl(f'cl{i}{j}', 0.085, 2.75, 2.78, 'steel', 24, center=(x, y, 0), r_in=0.07)]
    P(m, 'filter_bags_cages', 'Wire Cages & Bag Snap-Rings in the Tubesheet', 'filter', bg, explode=(0, -0.5, 0.3), ref='bh_bags', section='keep')
    bp = [cyl(f'bp{i}', 0.03, -D / 2 + 0.05, D / 2 + 0.25, 'steel', 12, axis='Y', center=(x, 0, 2.9)) for i, x in enumerate(xs)]
    bp += [cyl('hdr', 0.12, -0.8, 0.8, 'paint_blue', 24, axis='X', center=(0, D / 2 + 0.35, 2.9))] + [box(f'dv{i}', (0.1, 0.1, 0.1), (x, D / 2 + 0.25, 2.9), 'paint_blue_dark') for i, x in enumerate(xs)]
    bp += [box('tc', (0.3, 0.12, 0.4), (W / 2 + 0.3, D / 2, 2.0), 'paint_grey'), cyl('dpg', 0.05, -0.03, 0.0, 'glass', 16, axis='Y', center=(W / 2 + 0.3, 0, 1.9))]
    P(m, 'pulse_cleaning', 'Compressed-Air Header, Diaphragm Valves, Blowpipes (one per row) & Sequencer / ΔP Controller', 'cleaning', bp, explode=(0, 0.5, 0.4), ref='bh_cleaning', section='keep')
    for i, x in enumerate(xs):
        pb = P(m, f'filter_bags_row_{i + 1}', f'Filter Bags Row {i + 1} (needle-felt) — flex outward during the reverse pulse', 'filter', [cyl(f'pr{i}{j}', 0.075, 1.25, 2.75, 'cladding', 24, center=(x, y, 0), r_in=0.07) for j, y in enumerate(ys)],
               explode=(0, -0.5, 0.3), ref='bh_bags', section='keep', pivot=(x, 0, 2.0))
        keys_loop(m, pb, lambda t, i=i: (1 + 0.15 * smooth_pulse((t - i / 4) % 1.0, 0.02, 0.04, 0.06), 1 + 0.15 * smooth_pulse((t - i / 4) % 1.0, 0.02, 0.04, 0.06), 1), 'scale')
    rv = [cyl('rv', 0.15, -0.15, 0.15, 'cast_iron', 32, axis='Y', center=(0, 0, 0.45)), box('rvm', (0.2, 0.15, 0.15), (0, 0.25, 0.45), 'paint_motor')]
    P(m, 'rotary_valve', 'Rotary Airlock Valve (discharges dust, keeps air seal)', 'discharge', rv, explode=(0, 0, -0.3), ref='bh_discharge', section='keep')
    _fan_rotor(m, 'rotary_valve_rotor', 'Airlock Rotor', (0, 0, 0.45), 'Y', 0.13, 'bh_discharge', revs=1, n=8)
    dc = lathe('dc', [(0.0, 0.62), (0.16, 0.62), (0.6, 0.85), (0.0, 0.85)], 'powder', 4, a0=math.pi / 4, a1=math.pi / 4 + math.pi, cap_mat='powder')
    P(m, 'dust_in_hopper', 'Collected Dust in the Hopper', 'fluid', dc, explode=(0, -0.3, -0.2), ref='bh_discharge', section='keep')
    particles_path(m, 'dust', 'Dust caught on the bag surfaces (filter cake)', lambda i, s: (-W / 2 + 0.1 + 0.5 * s, -0.2 + 0.4 * ((i * 0.37) % 1), 1.4 + 0.3 * ((i * 0.53) % 1)), 12, mat='powder', r=0.02)
    droplets(m, 'cake_fall', 'Cake released by the pulse falls to the hopper', -0.6, 0.6, 1.2, 0.7, n=8, mat='powder', y=0.2, r=0.02)
    m.flow('dirty_gas', [(-W / 2 - 0.5, 0, 1.4), (-0.4, 0.05, 1.5), (-0.18, 0.15, 2.0), (-0.18, 0.0, 2.6)], 'flue_gas', 0.03, 0.4)
    m.flow('clean_gas', [(-0.18, 0, 2.75), (0.3, 0, 2.95), (W / 2 + 0.6, 0, 3.0)], 'air', 0.03, 0.4)
    m.flow('pulse_air', [(0.18, D / 2 + 0.35, 2.9), (0.18, 0.0, 2.9), (0.18, 0.0, 2.75)], 'air', 0.015, 0.2)
    _ov(m, 'pressure', [box('dz', (W - 0.1, 0.02, 1.4), (0, -D / 2 + 0.05, 2.0), 'pressure_6'), box('cz', (W - 0.1, 0.02, 0.2), (0, -D / 2 + 0.05, 2.9), 'pressure_2')], 'Filter on the outside, clean by a pulse',
        'Dirty gas flows from outside to inside through the bags; dust builds a cake that itself becomes the fine filter (outlet dust often < 5–10 mg/Nm³). As the cake grows the pressure drop rises (typically '
        'held ≈ 1–1.5 kPa); the controller then fires a short compressed-air pulse down each row in turn, flexing the bags so the cake drops to the hopper. Air-to-cloth ratio (≈ 0.8–1.5 m/min for pulse-jet) '
        'sets the bag area. Watch temperature (bag limits), dew point (wet cake) and spark ignition risk.')
    return m.export(out)


def _room(name, x0, x1, y0, y1, H, mat='paint_grey', t=0.06):
    return csg(name, [box(name + 'o', (x1 - x0 + 2 * t, y1 - y0 + 2 * t, H + t), ((x0 + x1) / 2, (y0 + y1) / 2, (H + t) / 2), mat)],
               [box(name + 'i', (x1 - x0, y1 - y0, H), ((x0 + x1) / 2, (y0 + y1) / 2, H / 2 + 0.001), mat)], mat)


# =============================================================== EQ-356 Ventilation system (supply AHU + exhaust)
def ventilation_system(out):
    m = _model('ventilation_system', 'Industrial Ventilation System — Supply Air Handling Unit, Ductwork & Diffusers, Exhaust Fan, Room Pressure Control')
    rm = _room('rm', -2.0, 2.0, -1.2, 1.2, 2.6)
    rm = csg('rm2', [rm], [box('dw', (0.8, 0.2, 2.0), (-1.0, -1.25, 1.0), 'paint_grey')], 'paint_grey')
    P(m, 'room', 'Process / Electrical Room (roof shown, front wall removed in cutaway)', 'building', rm, explode=(0, 0.8, 0), ref='vs_room')
    ah = [box('ahc', (1.8, 0.8, 0.8), (-0.6, 0, 3.1), 'paint_grey'), box('lv', (0.04, 0.6, 0.5), (-1.52, 0, 3.1), 'steel_dark'), box('pf', (0.05, 0.7, 0.7), (-1.25, 0, 3.1), 'cladding'), box('bf', (0.06, 0.7, 0.7), (-1.05, 0, 3.1), 'cladding'),
          box('cc', (0.12, 0.7, 0.7), (-0.8, 0, 3.1), 'copper'), box('hc', (0.08, 0.7, 0.7), (-0.6, 0, 3.1), 'hot_glow')]
    P(m, 'air_handling_unit', 'Roof AHU: Intake Louvre, Pre-Filter, Bag Filter, Cooling Coil, Heater, Supply Fan', 'ahu', ah, explode=(0, 0, 0.6), ref='vs_ahu', section='keep')
    _fan_rotor(m, 'supply_fan', 'Supply Fan', (-0.15, 0, 3.1), 'X', 0.3, 'vs_ahu', revs=4)
    dc = [hollow_pipe('sd', [(0.3, 0, 3.1), (0.6, 0, 3.1), (0.6, 0, 2.45), (0.6, 0.0, 2.3)], 0.18, 'aluminium', 24, bend=0.15), box('sdh', (2.8, 0.35, 0.3), (-0.2, 0.5, 2.3), 'aluminium')]
    dc += [cyl(f'df{k}', 0.15, 2.1, 2.15, 'steel', 24, center=(x, 0.5, 0)) for k, x in enumerate((-1.2, -0.2, 0.8))]
    P(m, 'supply_ductwork', 'Supply Ductwork & Ceiling Diffusers', 'ducts', dc, explode=(0, 0.3, 0.3), ref='vs_ducts', section='keep')
    ex = [box('eg', (0.4, 0.04, 0.4), (1.6, 1.18, 0.5), 'steel_dark'), hollow_pipe('ed', [(1.6, 1.1, 0.5), (1.6, 0.9, 0.5), (1.6, 0.9, 2.9), (1.6, 0.9, 3.3)], 0.15, 'aluminium', 24, bend=0.15),
          csg('eh', [cyl('eho', 0.3, 3.3, 3.6, 'paint_grey', 48, center=(1.6, 0.9, 0))], [cyl('ehi', 0.28, 3.28, 3.7, 'paint_grey', 48, center=(1.6, 0.9, 0))], 'paint_grey')]
    P(m, 'exhaust_system', 'Low-Level Exhaust Grille (heavier-than-air vapours) & Roof Exhaust Fan Housing', 'ducts', ex, explode=(0.3, 0.3, 0.3), ref='vs_exhaust', section='keep')
    _fan_rotor(m, 'exhaust_fan', 'Exhaust Fan Impeller', (1.6, 0.9, 3.45), 'Z', 0.25, 'vs_exhaust', revs=4)
    ct = [box('dp', (0.1, 0.06, 0.12), (-1.9, -0.6, 1.6), 'paint_blue_dark'), box('ts', (0.08, 0.05, 0.1), (-1.9, 0.6, 1.6), 'paint_blue_dark'), box('fd', (0.5, 0.4, 0.04), (-1.3, 0, 3.52), 'steel'),
          box('cab', (0.6, 0.4, 1.8), (0.6, -0.7, 0.9), 'paint_grey')]
    P(m, 'controls_equipment', 'Room ΔP & Temperature Sensors, Fire Damper, Electrical Cabinets (heat load)', 'controls', ct, explode=(0, -0.3, 0), ref='vs_controls', section='keep')
    for k, x in enumerate((-1.2, -0.2, 0.8)):
        add_tracers(m, f'supply_{k + 1}', f'Supply air from diffuser {k + 1}', [(x, 0.5, 2.1), (x, 0.4, 1.3), (x + 0.6, 0.6, 0.6), (1.6, 1.0, 0.5)], n=4, radius=0.03, mat='air')
    m.flow('supply_air', [(-1.6, 0, 3.1), (0.6, 0, 3.1), (0.6, 0.0, 2.3), (-1.2, 0.5, 2.3), (-1.2, 0.5, 2.1)], 'air', 0.03, 0.5)
    m.flow('exhaust_air', [(1.6, 1.15, 0.5), (1.6, 0.9, 0.5), (1.6, 0.9, 3.7)], 'exhaust', 0.03, 0.4)
    _ov(m, 'pressure', [box('rp', (3.9, 2.3, 0.02), (0, 0, 0.02), 'pressure_6'), box('op', (0.5, 0.5, 0.02), (-1.0, -1.6, 0.02), 'pressure_3')], 'Air changes, dilution and pressurisation',
        'Ventilation removes heat and dilutes contaminants: rooms are designed for an air-change rate (e.g. ≈ 6–12 per hour, or by heat load Q = P / (ρ·cp·ΔT)) and, in hazardous areas, enough dilution to keep '
        'gas below a fraction of its LEL. Supply slightly exceeding exhaust keeps electrical and control rooms at positive pressure (≈ 25–50 Pa) so dust and flammable gas cannot enter; low-level exhaust '
        'removes heavier-than-air vapours. Fire dampers close on fire alarm.')
    return m.export(out)


# =============================================================== EQ-357 Emergency ventilation fan
def emergency_ventilation_fan(out):
    m = _model('emergency_ventilation_fan', 'Emergency Ventilation Fan — Explosion-Proof Axial Wall Fan with Gravity Damper, Triggered by Gas Detection')
    wl = csg('wl', [box('wlo', (0.2, 3.0, 2.8), (0, 0, 1.4), 'cast_iron')], [cyl('wh', 0.52, -0.2, 0.2, 'cast_iron', 64, axis='X', center=(0, 0, 1.6))], 'cast_iron')
    P(m, 'wall', 'Building Wall (compressor / battery / analyser house)', 'building', wl, explode=(-0.3, 0, 0), ref='ef_wall')
    cs = csg('cs', [cyl('cso', 0.52, -0.3, 0.3, 'paint_yellow', 64, axis='X', center=(0, 0, 1.6)), cyl('csf', 0.62, 0.28, 0.32, 'paint_yellow', 64, axis='X', center=(0, 0, 1.6))],
             [cyl('csi', 0.5, -0.4, 0.4, 'paint_yellow', 64, axis='X', center=(0, 0, 1.6))], 'paint_yellow')
    P(m, 'fan_casing', 'Fan Casing (spark-resistant: non-sparking rotor/casing material pair)', 'casing', [cs] + [rotate(box(f'gv{k}', (0.2, 0.01, 0.45), (0.15, 0, 1.6 + 0.27), 'paint_yellow'), TAU * k / 7, 'X', (0, 0, 1.6)) for k in range(7)],
      explode=(0.3, 0.4, 0), ref='ef_casing')
    mt = [cyl('mt', 0.17, -0.25, 0.1, 'paint_motor', 48, axis='X', center=(0, 0, 1.6), ch=0.01), box('jb', (0.12, 0.12, 0.1), (-0.1, 0, 1.82), 'paint_motor')] + [rotate(box(f'st{k}', (0.06, 0.01, 0.34), (-0.1, 0, 1.6 + 0.33), 'steel'), TAU * k / 4 + 0.3, 'X', (0, 0, 1.6)) for k in range(4)]
    P(m, 'motor', 'Ex d Flameproof Motor (in the air stream) on Struts', 'drive', mt, explode=(-0.4, -0.3, 0.3), ref='ef_motor', section='keep')
    _fan_rotor(m, 'impeller', 'Aluminium / Bronze Axial Impeller (adjustable pitch)', (0.15, 0, 1.6), 'X', 0.46, 'ef_casing', revs=5, n=8)
    for k in range(5):
        z = 1.25 + 0.17 * k
        lv = P(m, f'damper_blade_{k + 1}', f'Gravity Back-Draught Damper Blade {k + 1} (opens with fan pressure)', 'damper', box(f'db{k}', (0.01, 1.1, 0.16), (0.36, 0, z + 0.08), 'aluminium'), explode=(0.4, 0, 0.1 * k), ref='ef_damper',
               section='keep', pivot=(0.36, 0, z + 0.16))
        keys_loop(m, lv, lambda t: (0, -1.2 * smooth_pulse(t, 0.15, 0.6, 0.15), 0), 'rotation_euler')
    P(m, 'damper_frame_guard', 'Damper Frame & Inlet Guard', 'damper', [csg('dfr', [box('dfo', (0.06, 1.2, 0.95), (0.36, 0, 1.6), 'aluminium')], [box('dfi', (0.1, 1.1, 0.86), (0.36, 0, 1.6), 'aluminium')], 'aluminium'),
                                                                          cyl('ig', 0.5, -0.32, -0.3, 'steel', 64, axis='X', center=(0, 0, 1.6), r_in=0.47)], explode=(0.5, 0, 0), ref='ef_damper', section='keep')
    gd = [_detector('gd', -0.14, 0.9, 0.45, facing=(0, 0, -1)), box('gdb', (0.04, 0.08, 0.08), (-0.12, 0.9, 0.5), 'paint_yellow'), box('cp', (0.15, 0.3, 0.4), (-0.18, -1.0, 1.4), 'paint_red'),
          box('bc', (0.12, 0.1, 0.12), (-0.16, -1.3, 2.4), 'paint_orange'), box('fl', (2.2, 3.0, 0.05), (-1.0, 0, -0.025), 'cast_iron')]
    P(m, 'detection_control', 'Gas Detector (low level), Fan Control Panel & Beacon (auto-start at ≈ 20 % LEL)', 'controls', gd, explode=(-0.3, -0.3, 0), ref='ef_controls', section='keep')
    add_tracers(m, 'signal', 'Gas alarm signal to the fan starter', [(-0.16, 0.9, 0.55), (-0.16, 0.0, 1.0), (-0.2, -0.85, 1.4), (-0.2, -0.4, 1.7)], n=3, radius=0.02, mat='electric')
    particles_path(m, 'gas_cloud', 'Leaked gas drawn out by the fan', lambda i, s: (-1.6 + 1.9 * s, -0.5 + 1.0 * ((i * 0.37) % 1) * (1 - s), 0.4 + 1.2 * s + 0.2 * ((i * 0.53) % 1) * (1 - s)), 14, mat='steam', r=0.04)
    m.flow('extract', [(-1.6, 0, 0.6), (-0.6, 0, 1.4), (0.0, 0, 1.6), (1.2, 0, 1.6)], 'exhaust', 0.04, 0.5)
    _ov(m, 'pressure', [cyl('pz', 0.5, -0.05, 0.05, 'pressure_7', 64, axis='X', center=(0, 0, 1.6), r_in=0.2), box('rz', (0.02, 2.8, 2.6), (-0.15, 0, 1.3), 'pressure_3')], 'Start on gas, purge fast, never ignite',
        'Emergency ventilation runs at high rate when gas detection reaches its first alarm (often ≈ 10–20 % LEL), diluting a leak below its flammable range and venting it outside. Equipment in the air '
        'stream must suit the hazardous-area zone (Ex d / Ex e motor, temperature class) and the impeller–casing pair must be non-sparking (e.g. aluminium/bronze vs steel) — a rub must not cause a spark. '
        'The gravity damper closes when the fan stops, keeping weather out. Supplies are typically on essential power.')
    return m.export(out)


# =============================================================== EQ-358 Fire & gas detection system
def fire_and_gas_detection_system(out):
    m = _model('fire_and_gas_detection_system', 'Fire & Gas Detection System on a Process Module — Point & Open-Path Gas, Flame, Heat Detectors, MCP, Alarms & F&G Panel')
    dk = [box('dk', (5.0, 3.0, 0.1), (0, 0, 0.05), 'steel_dark')] + [box(f'cl{k}', (0.15, 0.15, 3.0), (sx * 2.4, sy * 1.4, 1.55), 'paint_grey') for k, (sx, sy) in enumerate(((-1, -1), (-1, 1), (1, -1), (1, 1)))]
    dk += [box('rf', (5.0, 3.0, 0.08), (0, 0, 3.08), 'steel_dark')]
    P(m, 'module', 'Process Module / Skid Deck with Columns & Roof Deck', 'structure', dk, explode=(0, 0, -0.3), ref='fg_module', section='keep')
    eq = [vessel('v1', 0.45, 1.2, 0.01, 'paint_grey', heads=('2:1', '2:1'), z0=0.5, center=(-1.2, 0.4, 0)), legs('vl', 0.45, 0.1, 0.55, n=3, cx=-1.2, cy=0.4),
          hollow_pipe('pp', [(-0.75, 0.4, 1.0), (0.8, 0.4, 1.0), (0.8, 0.4, 0.5)], 0.08, 'steel', 16, bend=0.1), cyl('fl', 0.14, 0.15, 0.19, 'steel', 24, axis='X', center=(0, 0.4, 1.0)),
          box('cp', (0.9, 0.5, 0.5), (1.3, 0.4, 0.35), 'paint_blue')]
    P(m, 'process_equipment', 'Process Equipment (vessel, piping with flange — the leak source, compressor)', 'equipment', eq, explode=(0, 0.4, 0), ref='fg_equipment', section='keep')
    gd = [_detector('g1', -2.2, -1.2, 0.5, facing=(0, 0, -1)), _detector('g2', 0.0, -0.4, 0.5, facing=(0, 0, -1)), _detector('g3', 2.2, -1.2, 2.8, facing=(0, 0, -1)), _detector('g4', 0.5, 1.2, 2.8, facing=(0, 0, -1))]
    P(m, 'point_gas_detectors', 'Point Gas Detectors (IR hydrocarbon at low / high level by gas density; H₂S electrochemical)', 'detectors', gd, explode=(0, -0.3, 0.3), ref='fg_gas', section='keep')
    op = [box('opt', (0.15, 0.15, 0.2), (-2.3, -1.3, 1.6), 'paint_yellow'), box('opr', (0.15, 0.15, 0.2), (2.3, -1.3, 1.6), 'paint_yellow'), cyl('opb', 0.006, -2.22, 2.22, 'flame', 8, axis='X', center=(0, -1.3, 1.6))]
    P(m, 'open_path_detector', 'Open-Path (Line-of-Sight) Gas Detector: IR Transmitter → Receiver', 'detectors', op, explode=(0, -0.4, 0.2), ref='fg_gas', section='keep')
    fd = [_detector('f1', -2.3, 1.3, 2.7, mat='paint_red', facing=(1, -0.8, -0.6)), _detector('f2', 2.3, -1.3, 2.7, mat='paint_red', facing=(-1, 0.8, -0.6))]
    fd += [cyl('hd', 0.05, 2.97, 3.04, 'paint_red', 24, center=(-0.5, -0.3, 0)), box('mcp', (0.12, 0.06, 0.12), (-2.32, -1.0, 1.4), 'paint_red'), box('bcn', (0.1, 0.1, 0.14), (2.32, 1.0, 2.6), 'paint_orange'),
           cyl('hrn', 0.06, 2.25, 2.32, 'paint_red', 16, axis='X', center=(0, 1.0, 2.35))]
    P(m, 'flame_heat_alarm_devices', 'Flame Detectors (UV/IR, multi-IR), Heat Detector, Manual Call Point, Beacon & Horn', 'detectors', fd, explode=(0, 0.4, 0.3), ref='fg_fire', section='keep')
    pn = [box('pnl', (0.8, 0.4, 1.8), (0.0, 2.6, 0.9), 'paint_grey'), box('pns', (0.6, 0.01, 0.4), (0.0, 2.395, 1.45), 'pcb')] + [box(f'pl{k}', (0.05, 0.01, 0.05), (-0.25 + 0.1 * k, 2.39, 1.1), 'pressure_2' if k < 4 else 'pressure_9') for k in range(6)]
    P(m, 'fg_panel', 'F&G Logic Panel (SIL-rated): voting, alarms, executive actions (ESD, deluge, ventilation, isolation)', 'controls', pn, explode=(0, 0.5, 0), ref='fg_panel', section='keep')
    particles_path(m, 'gas_leak', 'Gas leaking from the flange and spreading', lambda i, s: (0.17 + 1.6 * s * math.cos(i * 1.3) * 0.6, 0.4 + 1.2 * s * math.sin(i * 1.3) * 0.6 - 0.6 * s, 1.0 - 0.5 * s * ((i * 0.37) % 1)), 18, mat='steam', r=0.05,
                   scale_fn=lambda i, s: 0.4 + 1.6 * s)
    add_tracers(m, 'signals', 'Detector signals to the F&G panel', [(0.0, -0.4, 0.6), (0.0, 0.0, 0.2), (0.0, 1.6, 0.2), (0.0, 2.4, 1.0)], n=4, radius=0.03, mat='electric')
    m.flow('signal_bus', [(-2.2, -1.2, 0.45), (-2.2, 1.5, 0.15), (0.0, 1.5, 0.15), (0.0, 2.4, 0.9)], 'electric', 0.015, 0.3)
    cones = []
    for k, (b, d) in enumerate((((-2.3, 1.3, 2.7), (1, -0.8, -0.6)), ((2.3, -1.3, 2.7), (-1, 0.8, -0.6)))):
        c = lathe(f'cv{k}', [(0.0, 0.0), (0.02, 0.0), (1.4, 3.0), (0.0, 3.0)], 'pressure_6', 24)
        dd = Vector(d).normalized()
        q = Vector((0, 0, 1)).rotation_difference(dd)
        c.data.transform(Matrix.Translation(Vector(b)) @ q.to_matrix().to_4x4())
        cones.append(c)
    cones.append(lathe('gz', [(0.0, 0.0), (0.6, 0.0), (0.6, 0.02), (0.0, 0.02)], 'pressure_8', 32, center=(0.2, 0.0, 0.11)))
    _ov(m, 'pressure', cones, 'Coverage: see the fire, smell the gas — then act', 'F&G detectors are placed by coverage mapping: flame detectors have a cone of vision (≈ 90° for UV/IR) and a range for a '
        'given fire size; gas detectors are placed where leaks would collect (low for heavier-than-air gas, high for lighter) and open-path detectors guard boundaries. Typical alarm levels: 20 % LEL low, '
        '50–60 % LEL high. The F&G logic uses voting (e.g. 2-out-of-N confirmed) to start executive actions: shutdown and isolation, deluge, ventilation changes and alarms.')
    return m.export(out)


# =============================================================== EQ-359 Firewater monitor
def firewater_monitor(out):
    m = _model('firewater_monitor', 'Firewater Monitor (Oscillating) on a Hydrant Riser — Swivel Joints, Adjustable Fog/Jet Nozzle')
    rs = [hollow_pipe('ug', [(-1.0, 0, -0.4), (0, 0, -0.4), (0, 0, 0.0)], 0.08, 'paint_red', 24, bend=0.1), hollow_pipe('rs', [(0, 0, 0.0), (0, 0, 1.0)], 0.075, 'paint_red', 24),
          _valve('iv', (0, 0, 0.5), 'Z', 0.075, 'paint_red', wheel_mat='steel'), box('pad', (0.6, 0.6, 0.1), (0, 0, 0.05), 'cast_iron'), box('gd', (0.06, 0.06, 0.1), (0.18, 0.0, 0.2), 'brass')]
    P(m, 'riser_valve', 'Underground Fire Main, Riser & Isolation Valve (drain at base)', 'piping', rs, explode=(0, 0, -0.3), ref='fm_riser', section='keep')
    th = lambda t: 0.5 * math.sin(TAU * t)
    mb = [cyl('sw1', 0.1, 1.0, 1.12, 'paint_red', 32), lathe('elb', [(0.0, 1.12), (0.09, 1.12), (0.09, 1.28), (0.0, 1.32)], 'paint_red', 32), cyl('sw2', 0.09, -0.08, 0.08, 'paint_red', 32, axis='Y', center=(0, 0, 1.32)),
          box('osc', (0.14, 0.12, 0.12), (-0.12, 0, 1.08), 'brass'), cyl('tl', 0.012, 1.3, 1.65, 'steel', 8, center=(-0.18, 0, 0))]
    nz = [cyl('bar', 0.065, 0.0, 0.45, 'paint_red', 32, axis='X'), lathe('nzl', [(0.0, 0.45), (0.065, 0.45), (0.045, 0.62), (0.03, 0.66), (0.0, 0.66)], 'brass', 32, axis='X'), cyl('nzr', 0.06, 0.6, 0.64, 'rubber', 32, axis='X', r_in=0.04)]
    for o in nz:
        o.data.transform(Matrix.Translation((0, 0, 1.32)) @ Matrix.Rotation(math.radians(-30), 4, 'Y'))
    jet = []
    v0, g = 9.0, 9.81
    for k in range(18):
        tt = 0.06 * (k + 1)
        x = 0.66 * math.cos(math.radians(30)) + v0 * math.cos(math.radians(30)) * tt * 0.6
        z = 1.32 + 0.66 * math.sin(math.radians(30)) + (v0 * math.sin(math.radians(30)) * tt - 0.5 * g * tt * tt) * 0.6
        if z < 0.05:
            break
        jet.append(ball(f'j{k}', 0.03 + 0.012 * k, 'water', (x, 0, z)))
    pm = P(m, 'monitor_head', 'Monitor Body: Horizontal & Vertical Swivel Joints, Water-Powered Oscillator, Tiller', 'monitor', mb + nz, explode=(0, 0, 0.4), ref='fm_monitor', section='keep', pivot=(0, 0, 1.05))
    pj = P(m, 'water_jet', 'Water Stream (straight jet ↔ fog pattern)', 'fluid', jet, explode=(0, 0, 0.4), ref='fm_monitor', section='keep', pivot=(0, 0, 1.05))
    for p in (pm, pj):
        for ms in p.meshes:
            axis_rot_keys(m, ms, (0, 0, 1), th)
    P(m, 'protected_equipment', 'Protected Equipment (tank / vessel being cooled)', 'equipment', [vessel('tk', 0.6, 1.2, 0.01, 'paint_grey', heads=('flat', '2:1'), z0=0.0, center=(4.5, 0, 0))], explode=(0.5, 0, 0), ref='fm_target', section='keep')
    m.flow('water', [(-1.0, 0, -0.4), (0, 0, -0.4), (0, 0, 1.32), (0.57, 0, 1.65)], 'water', 0.03, 0.4)
    arc = [sweep_tube('arc', [(0.57 + 3.5 * s, 0, 1.65 + 1.0 * math.sin(math.pi * s * 0.8) - 1.3 * s * s) for s in [j / 16 for j in range(17)]], 0.02, 'pressure_6', 8)]
    _ov(m, 'pressure', arc + [cyl('np', 0.07, 1.3, 1.36, 'pressure_8', 24, r_in=0.06)], 'Nozzle pressure sets reach and flow', 'A monitor delivers a large, aimable flow (≈ 1000–4000 L/min for typical plant monitors) at nozzle '
        'pressure ≈ 7 bar. Straight-stream reach can exceed ≈ 40–60 m; fog patterns give a shorter, wider cooling curtain to protect people and equipment from radiant heat. Oscillating monitors sweep '
        'automatically so the area can be cooled unattended. Flow ∝ √(pressure): Q = K·√P.')
    return m.export(out)


# =============================================================== EQ-360 Foam firefighting system
def foam_firefighting_system(out):
    m = _model('foam_firefighting_system', 'Foam Firefighting System — Bladder Tank, Ratio Proportioner, Deluge Valve & Foam Chambers on a Storage Tank')
    R, H = 1.6, 2.2
    tk = csg('tk', [cyl('tko', R + 0.02, 0.0, H, 'paint_grey', 96), lathe('rf', [(0.0, H), (R + 0.02, H), (0.0, H + 0.35)], 'paint_grey', 96)], [cyl('tki', R, 0.02, H + 0.01, 'paint_grey', 96), lathe('rfi', [(0.0, H - 0.01), (R, H - 0.01), (0.0, H + 0.33)], 'paint_grey', 96)], 'paint_grey')
    P(m, 'storage_tank', 'Fixed-Roof Hydrocarbon Storage Tank', 'tank', tk, explode=(0, 0.8, 0), ref='ff_tank')
    lq = lathe('lq', [(0.0, 0.02), (R - 0.005, 0.02), (R - 0.005, 1.6), (0.0, 1.6)], 'liquor', 96, a0=0.0, a1=math.pi, cap_mat='liquor')
    P(m, 'hydrocarbon', 'Stored Hydrocarbon', 'fluid', lq, explode=(0, -0.5, 0), ref='ff_tank', section='keep')
    fm = lathe('fb', [(0.0, 1.6), (R - 0.01, 1.6), (R - 0.01, 1.72), (0.0, 1.75)], 'foam', 96, a0=0.0, a1=math.pi, cap_mat='foam')
    pf = P(m, 'foam_blanket', 'Foam Blanket spreading over the burning surface', 'fluid', fm, explode=(0, -0.4, 0.3), ref='ff_foam', section='keep', pivot=(R * 0.95, 0, 1.6))
    keys_loop(m, pf, lambda t: (0.05 + 0.95 * min(1.0, t / 0.6), 0.05 + 0.95 * min(1.0, t / 0.6), 1), 'scale')
    fl = lathe('flm', [(0.0, 1.6), (R * 0.8, 1.6), (R * 0.6, 2.0), (R * 0.3, 2.4), (0.0, 2.6)], 'flame', 48)
    pfl = P(m, 'tank_fire', 'Surface Fire (extinguished as the foam covers it)', 'combustion', fl, explode=(0, -0.3, 0.6), ref='ff_tank', section='keep', pivot=(0, 0, 1.6))
    keys_loop(m, pfl, lambda t: (max(0.02, 1 - t / 0.65), max(0.02, 1 - t / 0.65), max(0.02, 1 - t / 0.65) * (1 + 0.08 * math.sin(TAU * 7 * t))), 'scale')
    ch = []
    for k, a in enumerate((math.pi / 2 - 0.5, math.pi / 2 + 0.5)):
        x, y = (R + 0.12) * math.cos(a), (R + 0.12) * math.sin(a)
        ch += [box(f'fc{k}', (0.25, 0.25, 0.4), (x, y, H - 0.1), 'paint_red'), cyl(f'fa{k}', 0.06, H + 0.1, H + 0.2, 'steel', 16, center=(x, y, 0)), hollow_pipe(f'fr{k}', [(x, y, H - 0.3), (x, y, 0.3), (x, y + 0.6, 0.3)], 0.05, 'paint_red', 16, bend=0.06),
               hollow_pipe(f'fd{k}', [(x, y, H - 0.2), (x * 0.94, y * 0.94, H - 0.2), (x * 0.9, y * 0.9, H - 0.4)], 0.05, 'steel', 12, bend=0.04)]
    P(m, 'foam_chambers', 'Foam Chambers / Makers on the Tank Shell (air inlet, vapour seal, deflector) & Risers', 'foam', ch, explode=(0, 0.5, 0.3), ref='ff_chambers', section='keep')
    bts = saddles('bts', (-2.9, -2.1), 0.4, 0.7)
    bts.data.transform(Matrix.Translation((0, 3.2, 0)))
    bt = [vessel('bt', 0.4, 1.4, 0.008, 'paint_red', axis='X', center=(0, 3.2, 0.7), heads=('2:1', '2:1'), z0=-3.2), bts]
    P(m, 'bladder_tank', 'Bladder Tank (foam concentrate inside a rubber bladder; water outside squeezes it out)', 'foam', bt, explode=(-0.4, 0.4, 0), ref='ff_bladder')
    bl = csg('bl', [cyl('blo', 0.33, -3.15, -1.85, 'paint_orange', 32, axis='X', center=(0, 3.2, 0.7))], [box('blh', (1.5, 0.8, 0.8), (-2.5, 3.2 - 0.4, 0.7), 'paint_orange')], 'paint_orange')
    pbl = P(m, 'bladder_concentrate', 'Bladder with AFFF / AR-AFFF Concentrate (1 % / 3 %)', 'fluid', bl, explode=(-0.4, -0.3, 0), ref='ff_bladder', section='keep', pivot=(-2.5, 3.2, 0.7))
    keys_loop(m, pbl, lambda t: (1, 1 - 0.4 * t, 1 - 0.4 * t), 'scale')
    pr = [hollow_pipe('wm', [(-4.2, 2.3, 0.3), (0.0, 2.3, 0.3)], 0.08, 'paint_red', 24), box('rc', (0.3, 0.25, 0.25), (-1.4, 2.3, 0.3), 'brass'), _valve('dv', (-2.9, 2.3, 0.3), 'X', 0.08, 'paint_red', wheel_mat='steel'),
          box('dva', (0.18, 0.12, 0.2), (-2.9, 2.3, 0.55), 'paint_red'), hollow_pipe('wb', [(-3.6, 2.3, 0.3), (-3.6, 3.2, 0.3), (-3.6, 3.2, 0.7), (-3.47, 3.2, 0.7)], 0.03, 'steel', 12, bend=0.04),
          hollow_pipe('cc', [(-1.83, 3.2, 0.7), (-1.4, 3.2, 0.7), (-1.4, 2.3, 0.45)], 0.03, 'steel', 12, bend=0.04), hollow_pipe('sol', [(0.0, 2.3, 0.3), (0.0, 1.75, 0.3)], 0.08, 'paint_red', 24),
          hollow_pipe('dst', [(0.0, 2.3, 0.3), (-0.55, 1.6, 0.3)], 0.06, 'paint_red', 16)]
    P(m, 'proportioning', 'Fire Water Main, Deluge Valve, Ratio Controller (proportioner) & Concentrate Line', 'piping', pr, explode=(-0.3, 0.3, 0), ref='ff_proportioner', section='keep')
    m.flow('water', [(-4.3, 2.3, 0.3), (-1.4, 2.3, 0.3)], 'water', 0.03, 0.4)
    m.flow('concentrate', [(-3.6, 2.3, 0.3), (-3.6, 3.2, 0.7), (-1.83, 3.2, 0.7), (-1.4, 3.2, 0.7), (-1.4, 2.3, 0.45)], 'flow_discharge', 0.02, 0.3)
    m.flow('foam_solution', [(-1.4, 2.3, 0.3), (0.0, 2.3, 0.3), (-0.46, 1.77, 0.3), (-0.46, 1.77, H - 0.3), (-0.42, 1.6, H - 0.4)], 'sand', 0.03, 0.4)
    _ov(m, 'pressure', [cyl('fz', R, 1.6, 1.62, 'pressure_2', 96, r_in=0.0), box('rz', (0.3, 0.25, 0.25), (-1.4, 2.3, 0.62), 'pressure_7')], 'Foam smothers, cools and seals the surface',
        'Water drawn through the ratio controller picks up foam concentrate at a fixed percentage (e.g. 3 %); the foam chambers aspirate air to expand it and pour it gently down the tank wall. The '
        'blanket spreads across the burning liquid, separating fuel from air, cooling it and suppressing vapour. Design follows NFPA 11 application rates (e.g. ≈ 4.1 L/min·m² for hydrocarbons with fixed '
        'outlets, longer times for some fuels — verify edition); polar solvents need alcohol-resistant foam.')
    return m.export(out)


